(function(root){'use strict';
let lastRun='',seen=-1,trauma=0,flash=0,cutin=null;const particles=[];
function observe(game){if(lastRun!==game.runId){seen=-1;lastRun=game.runId;particles.length=0;cutin=null;trauma=0;}for(const f of game.fx){if(f.id<=seen)continue;seen=Math.max(seen,f.id);if(['hit','hurt','death','impact','ultimate'].includes(f.type)){const count=f.type==='ultimate'?50:f.type==='impact'?24:12;for(let i=0;i<count&&particles.length<220;i++){const angle=(i*2.399+f.id),speed=70+(i%7)*35;particles.push({x:f.x,y:f.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed-65,life:.25+(i%5)*.09,max:.61,color:f.color||'#ff8066',size:i%4===0?5:2});}trauma=Math.max(trauma,f.type==='ultimate'?12:f.type==='impact'?6:f.type==='hurt'?4:2.5);if(f.type==='ultimate'){flash=.14;cutin={cls:f.cls,life:1,name:root.Rift.CLASSES[f.cls].skills[5].name,color:f.color};}}}}
function update(dt){trauma=Math.max(0,trauma-dt*23);flash=Math.max(0,flash-dt);if(cutin){cutin.life-=dt;if(cutin.life<=0)cutin=null;}for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.life<=0){particles.splice(i,1);continue;}p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=270*dt;}}
function arc(c,r,start,end,color,width,squeeze=.55){c.save();c.scale(1,squeeze);c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.beginPath();c.arc(20,0,r,start,end);c.stroke();c.restore();}
function effect(c,f,camera,time){if(['text','windup'].includes(f.type))return false;const age=1-f.life/(f.type==='ultimate'?1.15:.55),a=Math.min(1,f.life*4),range=f.range||140,color=f.color||'#f77c59',dir=f.dir||1;c.save();c.translate(f.x-camera,f.y-72);c.scale(dir,1);c.globalAlpha=a;c.globalCompositeOperation='lighter';
 if(['basic','cone','lift'].includes(f.type)){const radius=Math.min(330,range)*(.7+age*.4),turn=(f.combo%2?1:-1);c.rotate(f.type==='lift'?-1.1:turn*(-.45+age*.8));for(let i=4;i>=0;i--)arc(c,radius-i*5,-1.45+age*.6,1.25,color,i===0?3:10-i,.6);arc(c,radius-12,-1.35,1.1,'#fff4dc',3);for(let i=0;i<7;i++){c.fillStyle=color;c.fillRect(50+i*23,-30+(i%3)*24,30+age*40,2);}}
 else if(['line','chain'].includes(f.type)){const end=range*(.55+age*.45),w=(1-age)*26+3,g=c.createLinearGradient(0,0,end,0);g.addColorStop(0,color);g.addColorStop(.8,'#fff8ed');g.addColorStop(1,'#ffffff00');c.fillStyle=g;c.beginPath();c.moveTo(0,-w);c.lineTo(end+50,0);c.lineTo(0,w);c.fill();c.strokeStyle='#fff9ee';c.lineWidth=3;c.beginPath();c.moveTo(0,0);if(f.type==='chain')for(let i=1;i<12;i++)c.lineTo(end*i/12,Math.sin(i*7+f.id)*23*(1-age));c.lineTo(end,0);c.stroke();for(let i=0;i<5;i++){c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.ellipse(end*i/5,0,13+age*15,30+age*20,0,0,Math.PI*2);c.stroke();}}
 else if(['circle','pull','ultimate','impact'].includes(f.type)){c.translate(0,65);const r=range*(.3+age*.75);for(let i=0;i<3;i++){c.strokeStyle=i===1?'#fff0cb':color;c.lineWidth=i===1?2:7;c.beginPath();c.ellipse(0,0,r+i*14,(r+i*14)*.34,0,0,Math.PI*2);c.stroke();}for(let i=0;i<12;i++){const t=i*Math.PI/6+age*(f.type==='pull'?-2:1),x=Math.cos(t)*r,y=Math.sin(t)*r*.34;c.save();c.translate(x,y);c.rotate(t);c.fillStyle=color;c.beginPath();c.moveTo(-7,0);c.lineTo(0,-35*(1-age)-8);c.lineTo(7,0);c.fill();c.restore();}if(f.type==='ultimate'){for(let i=0;i<9;i++){const x=(i-4)*range/5;c.fillStyle=i%2?color:'#fff6dc';c.globalAlpha=a*.55;c.fillRect(x,-500*(1-age),4+i%3*6,520*(1-age));}}}
 else if(['dash','rush'].includes(f.type)){for(let i=0;i<9;i++){c.globalAlpha=a*(1-i/10);c.fillStyle=i%2?color:'#fff5db';c.fillRect(-220+age*120-i*18,-100+i*23,150+i*14,2+i%3);}}
 else if(['shield','heal'].includes(f.type)){for(let i=0;i<3;i++){c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.ellipse(0,-10,62+i*9+age*18,105+i*11,0,-Math.PI*age,Math.PI*(2-age));c.stroke();}if(f.type==='heal'){c.fillStyle='#a4f8c3';for(let i=0;i<6;i++){const x=Math.sin(i*8)*55,y=20-i*25-age*80;c.fillRect(x-3,y-9,6,18);c.fillRect(x-9,y-3,18,6);}}}
 else if(['hit','hurt','death'].includes(f.type)){c.strokeStyle='#fff7dc';c.lineWidth=f.type==='death'?5:3;c.beginPath();c.moveTo(-40*(1-age),-45*(1-age));c.lineTo(40*(1-age),45*(1-age));c.moveTo(35*(1-age),-45*(1-age));c.lineTo(-35*(1-age),45*(1-age));c.stroke();}
 else{c.restore();return false;}c.restore();return true;}
function overlay(c,camera,images){c.save();c.globalCompositeOperation='lighter';for(const p of particles){c.globalAlpha=Math.max(0,p.life/p.max);c.fillStyle=p.color;c.save();c.translate(p.x-camera,p.y);c.rotate(Math.atan2(p.vy,p.vx));c.fillRect(-p.size,-1,p.size*3,2);c.restore();}c.restore();if(flash>0){c.fillStyle='rgba(255,242,218,'+flash*2+')';c.fillRect(0,0,1600,800);}if(cutin){const t=cutin.life,slide=Math.min(1,(1-t)*8),x=-460+(slide*460);c.save();c.globalAlpha=Math.min(1,t*4);c.fillStyle='#0a101eed';c.beginPath();c.moveTo(x,210);c.lineTo(x+650,210);c.lineTo(x+565,410);c.lineTo(x,410);c.fill();c.fillStyle=cutin.color;c.fillRect(x,409,565,3);if(images.fighters){const im=images.fighters,sw=im.width/4;c.save();c.beginPath();c.rect(x,210,325,200);c.clip();c.drawImage(im,sw*cutin.cls,0,sw,im.height,x+20,150,310,620);c.restore();}c.font='700 28px "Rift UI",sans-serif';c.fillStyle='#fff1d3';c.textAlign='left';c.fillText(cutin.name,x+300,325);c.restore();}}
root.DungeonEffects={observe,update,effect,overlay,shake:time=>root.DungeonSound.settings().shake?[Math.sin(time*83)*trauma,Math.cos(time*91)*trauma*.6]:[0,0],stats:()=>({particles:particles.length,trauma})};
})(window);
